<script setup lang="ts">
import SubscriptionAlertPolicyEditor from "../components/notifications/SubscriptionAlertPolicyEditor.vue";
import ResellerDefaultsEditor from "../components/ResellerDefaultsEditor.vue";
import QrPolicyEditor from "../components/QrPolicyEditor.vue";
import TrialPolicyEditor from "../components/trials/TrialPolicyEditor.vue";
import { computed, onMounted, ref } from "vue";
import { useI18n } from "vue-i18n";
import { item, request, query, type PreferencesSnapshot, type PreferencesRevision, type Page, type FulfillmentPolicy, type QuotaPolicy } from "@papilio/api";
import { useAuth } from "@papilio/auth";
import { asciiDigits, faDate, faNumber, toman } from "@papilio/ui";
import { kinds as notificationKinds } from "../components/notifications/labels";
import NotificationPolicyEditor from "../components/notifications/NotificationPolicyEditor.vue";
import SupportPolicyEditor from "../components/support/SupportPolicyEditor.vue";
import BotPresentationEditor from "../components/bot/BotPresentationEditor.vue";
import QuotaPolicyEditor from "../components/QuotaPolicyEditor.vue";
import FulfillmentPolicyEditor from "../components/FulfillmentPolicyEditor.vue";
import NumField from "@papilio/ui/NumField.vue";
import { useBranding } from "../stores/branding";
import PurchaseCheckoutPolicyEditor from "../components/PurchaseCheckoutPolicyEditor.vue";
import CheckoutPolicyEditor from "../components/CheckoutPolicyEditor.vue";
const auth = useAuth(); const branding = useBranding(); const { t } = useI18n();
const snapshot = ref<PreferencesSnapshot | null>(null); const error = ref(""); const notice = ref(""); const busy = ref(false); const state = ref<"loading" | "ready" | "error">("loading");
const allowRotation = ref(false); const brand = ref(""); const instructions = ref(""); const support = ref(""); const amounts = ref(""); const mode = ref<"reject_new" | "replace_oldest">("reject_new"); const maxIps = ref(""); const lease = ref(""); const ban = ref("");
const fields = [{ key: "max_plan_duration_days", label: "settingsForm.maxPlanDuration" }, { key: "payment_stale_hours", label: "settingsForm.paymentWaiting" }, { key: "node_health_stale_seconds", label: "settingsForm.nodeSampleStale" }, { key: "subscription_expiry_warning_hours", label: "settingsForm.expiryWarning" }, { key: "provisioning_attention_minutes", label: "settingsForm.provisionWarning" }] as const;
type NumericKey = typeof fields[number]["key"];
const numbers = ref<Record<NumericKey, string>>({ max_plan_duration_days: "", payment_stale_hours: "", node_health_stale_seconds: "", subscription_expiry_warning_hours: "", provisioning_attention_minutes: "" });
const receipts = ref<import("@papilio/api").ReceiptPolicy|null>(null); const receiptCount=ref("");
const resellerDefaults=ref<import("@papilio/api").ResellerDefaults|null>(null);
const qrPolicy=ref<import("@papilio/api").QrPolicy|null>(null);
const trialPolicy=ref<import("@papilio/api").TrialPolicy|null>(null);
const purchaseDraftValid=ref(true);
const identifierDraftValid=ref(true);
const supportedNoticeKinds=computed(()=>snapshot.value?.capabilities?.supported_notification_kinds);
const transientModes=computed(()=>snapshot.value?.capabilities?.checkout_transient_conflict_modes??[]);
const purchaseSupported=ref(false);
const purchasePolicy=ref<import("@papilio/api").PurchaseCheckoutPolicy|null>(null);
const alertsSupported=ref(false);
const alertPolicy=ref<import("@papilio/api").SubscriptionAlertPolicy>({enabled:false,low_quota:[],expiry_hours:[],renewal_opportunity:false});
const notificationPolicy=ref<import("@papilio/api").NotificationPolicy|null>(null);
const supportPolicy=ref<import("@papilio/api").SupportPolicy|null>(null);
const botPresentation=ref<import("@papilio/api").BotPresentationSettings|null>(null);
const creationAccess = ref<import("@papilio/api").CustomerAccessState|null>(null);
const checkout = ref<import("@papilio/api").CheckoutPolicy | null>(null);
const quotaPolicy = ref<QuotaPolicy | null>(null); const fulfillment = ref<FulfillmentPolicy | null>(null); const defaultIpEnabled = ref(false);
const history = ref<PreferencesRevision[]>([]); const historyState = ref<"loading" | "ready" | "error">("loading"); const page = ref(1); const pages = ref(1);
async function load(): Promise<void> {
  state.value = "loading"; error.value = "";
  try {
    const result = await item<PreferencesSnapshot>("/v1/admin/settings"); snapshot.value = result; purchaseSupported.value=Object.prototype.hasOwnProperty.call(result.values,"purchase_checkout");purchasePolicy.value=structuredClone(result.values.purchase_checkout??null); alertsSupported.value=Object.prototype.hasOwnProperty.call(result.values,"subscription_alerts"); alertPolicy.value=structuredClone(result.values.subscription_alerts??{enabled:false,low_quota:[],expiry_hours:[],renewal_opportunity:false}); resellerDefaults.value=structuredClone(result.values.reseller_defaults??null); qrPolicy.value=structuredClone(result.values.qr_codes??null); trialPolicy.value=structuredClone(result.values.trials??null); notificationPolicy.value=structuredClone(result.values.notifications??null); supportPolicy.value=structuredClone(result.values.support??null); const values = result.values; botPresentation.value=structuredClone(values.bot_presentation);
    creationAccess.value = {...values.customer_creation_access}; allowRotation.value = values.customer_link_rotation; brand.value = values.brand_title; instructions.value = values.payment_instructions ?? ""; support.value = values.support_handle ?? ""; amounts.value = values.topup_options_rial.map(value => String(value / 10)).join("\n");
    receipts.value=structuredClone(values.receipts);receiptCount.value=String(values.receipts.max_per_topup); checkout.value = structuredClone(values.checkout); quotaPolicy.value = { ...values.quota_policy }; fulfillment.value = { ...values.fulfillment }; defaultIpEnabled.value = values.ip_defaults.enabled; mode.value = values.ip_defaults.mode; maxIps.value = String(values.ip_defaults.max_ips); lease.value = String(values.ip_defaults.lease_seconds); ban.value = String(values.ip_defaults.ban_seconds);
    for (const field of fields) numbers.value[field.key] = String(values[field.key]); state.value = "ready";
  } catch (cause) { state.value = "error"; error.value = cause instanceof Error ? cause.message : t("errors.request_failed"); }
}
async function loadHistory(): Promise<void> {
  historyState.value = "loading"; const requested = page.value;
  try { const result = await request<Page<PreferencesRevision>>(`/v1/admin/settings/history?${query({ page: requested })}`); if (page.value !== requested) return; history.value = result.data; pages.value = result.meta.pager?.total_pages ?? 1; historyState.value = "ready"; }
  catch (cause) { historyState.value = "error"; error.value = cause instanceof Error ? cause.message : t("errors.request_failed"); }
}
async function save(): Promise<void> {
  if (!snapshot.value) return; if(!identifierDraftValid.value){error.value=t("settingsForm.identifierInvalid");return;} if(purchaseSupported.value&&!purchaseDraftValid.value){error.value=t("settingsForm.checkoutLifetimeRequired");return;} busy.value = true; error.value = ""; notice.value = "";
  try {
    const options = asciiDigits(amounts.value).replace(/٫/g, ".").split(/[\s,،]+/).filter(Boolean);
    if (!options.length || options.some(value => !/^\d+(?:\.\d)?$/.test(value))) throw new Error(t("settingsForm.topupAmountFormat"));
    const values = { ...(purchaseSupported.value?{purchase_checkout:purchasePolicy.value}:{}), ...(alertsSupported.value?{subscription_alerts:alertPolicy.value}:{}), reseller_defaults:resellerDefaults.value, qr_codes:qrPolicy.value, trials:trialPolicy.value, notifications: notificationPolicy.value, support: supportPolicy.value, customer_creation_access: creationAccess.value, receipts: receipts.value ? {...receipts.value,max_per_topup:Number(receiptCount.value)} : null, checkout: checkout.value, quota_policy: quotaPolicy.value, customer_link_rotation: allowRotation.value, bot_presentation: botPresentation.value, brand_title: brand.value, payment_instructions: instructions.value.trim() || null, support_handle: support.value.trim() || null, topup_options_rial: options.map(value => Math.round(Number(value) * 10)), max_plan_duration_days: Number(numbers.value.max_plan_duration_days), payment_stale_hours: Number(numbers.value.payment_stale_hours), node_health_stale_seconds: Number(numbers.value.node_health_stale_seconds), subscription_expiry_warning_hours: Number(numbers.value.subscription_expiry_warning_hours), provisioning_attention_minutes: Number(numbers.value.provisioning_attention_minutes), fulfillment: fulfillment.value, ip_defaults: { enabled: defaultIpEnabled.value, mode: mode.value, max_ips: Number(maxIps.value), lease_seconds: Number(lease.value), ban_seconds: Number(ban.value) } };
    snapshot.value = await item<PreferencesSnapshot>("/v1/admin/settings", "PUT", { expected_revision: snapshot.value.revision, values }); notice.value = t("settingsForm.saved"); await branding.refresh(); page.value = 1; await loadHistory();
  } catch (cause) { error.value = cause instanceof Error ? cause.message : t("errors.request_failed"); } finally { busy.value = false; }
}
onMounted(async () => { await load(); await loadHistory(); });
</script>
<template>
  <div class="page-head"><div><p class="eyebrow">{{ t('settings.eyebrow') }}</p><h1>{{ t('settings.title') }}</h1><p class="subtitle">{{ t('settings.description') }}</p></div><button class="btn secondary" :disabled="busy" @click="load">{{ t('settings.reload') }}</button></div>
  <p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message" role="status">{{ notice }}</p><p v-if="state === 'loading'">{{t("settingsForm.loading")}}</p>
  <form v-if="snapshot" class="card card-pad form-grid" @submit.prevent="save"><h2>{{t("settingsForm.revision")}} {{ faNumber(snapshot.revision) }}</h2><fieldset :disabled="!auth.can('settings', 'update') || busy" class="form-grid"><label class="field"><span>{{t("settingsForm.brandName")}}</span><input v-model="brand" required minlength="2" maxlength="100" /></label><label class="field"><span>{{t("settingsForm.paymentInstructions")}}</span><textarea v-model="instructions" rows="5" maxlength="4000" /></label><label class="field"><span>{{t("settingsForm.supportHandle")}}</span><input v-model="support" dir="ltr" /></label><BotPresentationEditor v-if="botPresentation" v-model="botPresentation" :disabled="busy || !auth.can('settings', 'update')" /><label class="field"><span>{{t("settingsForm.suggestedTopups")}}</span><textarea v-model="amounts" rows="4" /></label><NumField v-for="field in fields" :key="field.key" v-model="numbers[field.key]" :label="t(field.label)" /><label class="check-row"><input v-model="allowRotation" type="checkbox" />{{t("settingsForm.linkRotation")}}</label><h3>{{t("settingsForm.customerDefaults")}}</h3><template v-if="creationAccess"><label class="check-row"><input v-model="creationAccess.is_active" type="checkbox" />{{t("settingsForm.accountSignin")}}</label><label class="check-row"><input v-model="creationAccess.services_enabled" type="checkbox" />{{t("settingsForm.purchaseAccess")}}</label><label class="check-row"><input v-model="creationAccess.renewals_enabled" type="checkbox" />{{t("settingsForm.renewalAccess")}}</label></template><h3>{{t("settingsForm.receiptPolicy")}}</h3><template v-if="receipts"><label class="check-row"><input v-model="receipts.enabled" type="checkbox" />{{t("settingsForm.receiptUploads")}}</label><NumField v-model="receiptCount"  :label="t('settingsForm.maxReceipts')" /><label v-for="format in (['JPEG','PNG','WEBP'] as const)" :key="format" class="check-row"><input v-model="receipts.allowed_formats" :value="format" type="checkbox" />{{ format === 'JPEG' ? t('settingsForm.jpeg') : format === 'PNG' ? t('settingsForm.png') : t('settingsForm.webp') }}</label></template><h3>{{t("settingsForm.supportPolicy")}}</h3><h3 v-if="notificationPolicy">{{t("settingsForm.notificationPolicy")}}</h3><QrPolicyEditor v-if="qrPolicy" v-model="qrPolicy" /><TrialPolicyEditor v-if="trialPolicy" v-model="trialPolicy" :disabled="!auth.can('settings','update')" /><SubscriptionAlertPolicyEditor v-if="alertsSupported" v-model="alertPolicy" /><p v-else class="hint-box" role="status">{{t("settingsForm.alertUnavailable")}}</p><NotificationPolicyEditor v-if="notificationPolicy" v-model="notificationPolicy" :supported-kinds="supportedNoticeKinds" /><SupportPolicyEditor v-if="supportPolicy" v-model="supportPolicy" /><PurchaseCheckoutPolicyEditor v-if="purchaseSupported" v-model="purchasePolicy" :transient-modes="transientModes" @valid="purchaseDraftValid=$event" /><p v-else class="hint-box">{{t("settingsForm.purchaseUnavailable")}}</p><h3>{{t("settingsForm.topupPolicy")}}</h3><CheckoutPolicyEditor v-if="checkout" v-model="checkout" :identifier-capabilities="snapshot.capabilities?.payment_identifiers" @valid="identifierDraftValid=$event" /><ResellerDefaultsEditor v-if="resellerDefaults" v-model="resellerDefaults" :disabled="busy||!auth.can('settings','update')"/><h3>{{t("settingsForm.provisionDefaults")}}</h3><p>{{t("settingsForm.provisionHint")}}</p><FulfillmentPolicyEditor v-if="fulfillment" v-model="fulfillment" /><h3>{{t("settingsForm.quotaDefaults")}}</h3><QuotaPolicyEditor v-if="quotaPolicy" v-model="quotaPolicy" /><h3>{{t("settingsForm.ipDefaults")}}</h3><label class="check-row"><input v-model="defaultIpEnabled" type="checkbox" />{{t("settingsForm.ipApplyDefault")}}</label><p>{{t("settingsForm.ipHint")}}</p><NumField v-model="maxIps" :label="t('settingsForm.activeIpLimit')" /><NumField v-model="lease" :label="t('settingsForm.leaseDuration')" /><NumField v-model="ban" :label="t('settingsForm.banDuration')" /><label class="field"><span>{{t("settingsForm.extraIpBehavior")}}</span><select v-model="mode"><option value="reject_new">{{t("settingsForm.rejectNewIp")}}</option><option value="replace_oldest">{{t("settingsForm.replaceOldestIp")}}</option></select></label><button v-if="auth.can('settings', 'update')" class="btn" :disabled="busy || state !== 'ready' || !purchaseDraftValid">{{t("settingsForm.save")}}</button></fieldset></form>
  <section class="card card-pad" style="margin-top:18px"><h2>{{t("settingsForm.history")}}</h2><button class="btn secondary" @click="loadHistory">{{t("settingsForm.refreshHistory")}}</button><p v-if="historyState === 'loading'">{{t("settingsForm.historyLoading")}}</p><p v-else-if="historyState === 'error'" class="message error">{{t("settingsForm.historyError")}}</p><p v-else-if="!history.length">{{t("settingsForm.noHistory")}}</p><details v-for="row in history" :key="row.revision"><summary>Revision {{ faNumber(row.revision) }} · {{ row.created_at ? faDate(row.created_at) : '—' }} · Operator {{ faNumber(row.changed_by_staff_id) }}</summary><dl><dt>{{t("settingsForm.brand")}}</dt><dd>{{ row.values.brand_title }}</dd><dt>{{t("settingsForm.paymentInstructions")}}</dt><dd>{{ row.values.payment_instructions ?? '—' }}</dd><dt>{{t("settingsForm.support")}}</dt><dd>{{ row.values.support_handle ?? '—' }}</dd><template v-if="row.values.bot_presentation"><dt>{{t("botPresentation.welcome")}}</dt><dd>{{row.values.bot_presentation.localized_texts.fa.welcome_message}}</dd><dt>{{t("botPresentation.photoUrl")}}</dt><dd>{{row.values.bot_presentation.welcome_photo_url ?? '—'}}</dd></template><dt>{{t("settingsForm.topupAmounts")}}</dt><dd>{{ row.values.topup_options_rial.map(toman).join(', ') }}</dd><template v-for="field in fields" :key="field.key"><dt>{{ t(field.label) }}</dt><dd>{{ faNumber(row.values[field.key]) }}</dd></template><template v-if="row.values.quota_policy"><dt>{{t("settingsForm.quotaMode")}}</dt><dd>{{ row.values.quota_policy.mode === 'reserved' ? t("settingsForm.sharedReservation") : t("settingsForm.reportUsage") }} · {{ faNumber(row.values.quota_policy.grant_bytes) }} bytes · {{ faNumber(row.values.quota_policy.grant_seconds) }} seconds</dd></template><template v-if="row.values.fulfillment"><dt>{{t("settingsForm.renewalTrigger")}}</dt><dd>{{ row.values.fulfillment.renewal_trigger === 'quota' ? t("settingsForm.quotaExhausted") : row.values.fulfillment.renewal_trigger === 'either' ? t("settingsForm.expiryOrQuota") : t("settingsForm.expiry") }}</dd></template><template v-if="row.values.checkout"><dt>{{t("settingsForm.destinationSelection")}}</dt><dd>{{ row.values.checkout.destination_mode === 'required' ? t("settingsForm.required") : row.values.checkout.destination_mode === 'optional' ? t("settingsForm.optional") : t("settingsForm.legacyInstructions") }} · {{ toman(row.values.checkout.minimum_topup_rial) }} to {{ toman(row.values.checkout.maximum_topup_rial) }}</dd></template><template v-if="row.values.checkout?.payment_identifier"><dt>{{t("settingsForm.paymentIdentifier")}}</dt><dd>{{row.values.checkout.payment_identifier.mode}} · maximum adjustment {{row.values.checkout.payment_identifier.max_adjustment_rial}} RIAL · step {{row.values.checkout.payment_identifier.amount_step_rial}} RIAL</dd></template><template v-if="row.values.receipts"><dt>{{t("settingsForm.receiptUploads")}}</dt><dd>{{ row.values.receipts.enabled ? t("settingsForm.enabled") : 'Inactive' }} · {{ faNumber(row.values.receipts.max_per_topup) }} Receipt</dd></template><template v-if="row.values.trials"><dt>{{t("settingsForm.trialPolicy")}}</dt><dd>{{row.values.trials.enabled?t("settingsForm.active"):t("settingsForm.paused")}} · Plan {{row.values.trials.plan_id===null?'Not selected':faNumber(row.values.trials.plan_id)}} · {{row.values.trials.eligibility==='no_paid_purchase'?t("settingsForm.noPaidPurchases"):t("settingsForm.anyCustomer")}} · {{row.values.trials.concurrent_mode==='reject_active'?t("settingsForm.rejectConcurrent"):t("settingsForm.allowMultiple")}} · {{faNumber(row.values.trials.max_claims_per_customer)}} Download · {{faNumber(row.values.trials.cooldown_seconds)}} seconds between claims · {{faNumber(row.values.trials.quota_bytes)}} bytes · {{faNumber(row.values.trials.duration_days)}} days</dd></template><template v-if="row.values.purchase_checkout"><dt>{{t("settingsForm.automatedPurchase")}}</dt><dd>{{row.values.purchase_checkout.enabled?"Enabled":"Disabled"}} · {{row.values.purchase_checkout.admission_mode==="require_ready_bundle"?"Available bundle required":"Manual configuration allowed"}} · {{faNumber(row.values.purchase_checkout.default_expiry_seconds)}} seconds</dd></template><dt>{{t("settingsForm.alertRules")}}</dt><dd>{{row.values.subscription_alerts?.enabled?"Enabled":"Disabled"}} · {{row.values.subscription_alerts?.low_quota.length??0}} quota rules · {{row.values.subscription_alerts?.expiry_hours.join(", ")||"No expiry rules"}}</dd><template v-if="row.values.notifications"><dt>{{t("settingsForm.notificationPolicy")}}</dt><dd>{{row.values.notifications.enabled?t("settingsForm.active"):t("settingsForm.paused")}} · {{row.values.notifications.channel_mode==='inbox'?'Inbox':row.values.notifications.channel_mode==='telegram'?'Telegram':'Inbox and Telegram'}} · {{row.values.notifications.delivery_enabled?t("settingsForm.deliveryEnabled"):t("settingsForm.deliveryPaused")}} · {{row.values.notifications.ambiguous_mode==='hold'?t("settingsForm.holdUncertain"):t("settingsForm.retryUncertain")}} · {{row.values.notifications.backoff_mode==='fixed'?t("settingsForm.fixedDelay"):t("settingsForm.exponentialDelay")}} · {{faNumber(row.values.notifications.retry_seconds)}} to {{faNumber(row.values.notifications.max_retry_seconds)}} seconds · {{faNumber(row.values.notifications.max_attempts)}} attempts · {{faNumber(row.values.notifications.lease_seconds)}} seconds reserved · {{faNumber(row.values.notifications.max_message_chars)}} characters</dd><template v-for="(template,key) in row.values.notifications.templates" :key="key"><dt>Template {{notificationKinds[key]}}</dt><dd v-if="template">{{template.enabled?t("settingsForm.active"):t("settingsForm.paused")}} · {{template.title}} · {{template.body}}</dd><dd v-else>Not configured</dd></template></template><template v-if="row.values.support"><dt>{{t("settingsForm.ticketPolicy")}}</dt><dd>{{row.values.support.new_tickets_enabled?t("settingsForm.newTicketsEnabled"):t("settingsForm.newTicketsPaused")}} · {{row.values.support.customer_replies_enabled?t("settingsForm.customerRepliesEnabled"):t("settingsForm.customerRepliesPaused")}} · {{row.values.support.staff_replies_enabled?t("settingsForm.staffRepliesEnabled"):t("settingsForm.staffRepliesPaused")}} · {{faNumber(row.values.support.max_open_tickets)}} open tickets · {{faNumber(row.values.support.max_messages_per_ticket)}} Message · {{faNumber(row.values.support.max_message_chars)}} characters · {{row.values.support.closed_reply_mode==='reject'?t("settingsForm.rejectClosedReplies"):t("settingsForm.acceptClosedReplies")}} · {{row.values.support.customer_closure_enabled?t("settingsForm.customerClosureEnabled"):t("settingsForm.customerClosurePaused")}} · {{row.values.support.customer_reopen_enabled?t("settingsForm.customerReopenEnabled"):t("settingsForm.customerReopenPaused")}} · {{row.values.support.staff_reply_status==='open'?t("settingsForm.waitingForSupport"):row.values.support.staff_reply_status==='closed'?'Closed':t("settingsForm.waitingForCustomer")}}</dd></template><template v-if="row.values.qr_codes"><dt>{{t("settingsForm.qrCode")}}</dt><dd>{{row.values.qr_codes.enabled?t("settingsForm.active"):t("settingsForm.paused")}} · {{faNumber(row.values.qr_codes.box_size)}} pixels · {{faNumber(row.values.qr_codes.border_modules)}} border modules · {{({L:t("settingsForm.low"),M:t("settingsForm.medium"),Q:t("settingsForm.high"),H:t("settingsForm.maximum")})[row.values.qr_codes.error_correction]}}</dd></template><template v-if="row.values.reseller_defaults"><dt>{{t("settingsForm.resellerDefaults")}}</dt><dd><ResellerDefaultsEditor :model-value="row.values.reseller_defaults" disabled/></dd></template><dt>{{t("settingsForm.ipPolicy")}}</dt><dd>{{ faNumber(row.values.ip_defaults.max_ips) }} · Validity {{ faNumber(row.values.ip_defaults.lease_seconds) }} seconds · Ban {{ faNumber(row.values.ip_defaults.ban_seconds) }} seconds · {{ row.values.ip_defaults.mode === 'reject_new' ? 'Reject new IP' : t("settingsForm.replaceOldestIp") }}</dd></dl></details><div class="pager"><button :disabled="page <= 1" @click="page--; loadHistory()">‹</button><span>{{ faNumber(page) }}</span><button :disabled="page >= pages" @click="page++; loadHistory()">›</button></div></section>
</template>

<style scoped>
